1	// A thin, mockable wrapper around navigator.geolocation / navigator.permissions.
2	// Keeping the browser API behind this boundary is what lets stylist.tsx stay
3	// declarative and lets the tests run in jsdom, which has neither API.
4	
5	export type GeoErrorKind = "denied" | "unavailable" | "timeout" | "unsupported";
6	
7	export class GeoError extends Error {
8	  readonly kind: GeoErrorKind;
9	  constructor(kind: GeoErrorKind) {
10	    super(`geolocation: ${kind}`);
11	    this.name = "GeoError";
12	    this.kind = kind;
13	  }
14	}
15	
16	/** PositionError codes: 1 PERMISSION_DENIED · 2 POSITION_UNAVAILABLE · 3 TIMEOUT */
17	function kindFor(code: number): GeoErrorKind {
18	  if (code === 1) return "denied";
19	  if (code === 3) return "timeout";
20	  return "unavailable";
21	}
22	
23	export function getCurrentPosition(): Promise<{ lat: number; lon: number }> {
24	  return new Promise((resolve, reject) => {
25	    if (typeof navigator === "undefined" || !navigator.geolocation) {
26	      reject(new GeoError("unsupported"));
27	      return;
28	    }
29	    navigator.geolocation.getCurrentPosition(
30	      (p) => resolve({ lat: p.coords.latitude, lon: p.coords.longitude }),
31	      (e) => reject(new GeoError(kindFor(e.code))),
32	      { timeout: 10_000, maximumAge: 300_000 },
33	    );
34	  });
35	}
36	
37	/**
38	 * "granted" is the only state that authorises a SILENT read on load — querying
39	 * permissions never shows a prompt, but getCurrentPosition would.
40	 */
41	export async function permissionState(): Promise<"granted" | "prompt" | "denied" | "unsupported"> {
42	  if (typeof navigator === "undefined" || !navigator.geolocation) return "unsupported";
43	  if (!navigator.permissions?.query) return "prompt"; // older Safari — tap path only
44	  try {
45	    const status = await navigator.permissions.query({ name: "geolocation" as PermissionName });
46	    return status.state;
47	  } catch {
48	    return "prompt";
49	  }
50	}
