15	  cities = [],
16	  onSearch,
17	  onCityChange,
18	  onUseMyLocation,
19	  locating = false,
20	  geoError = null,
21	}: {
22	  weather: WeatherPayload;
23	  cities?: City[];
24	  onSearch?: (q: string) => void;
25	  onCityChange?: (c: City) => void;
26	  onUseMyLocation?: () => void;
27	  locating?: boolean;
28	  geoError?: string | null;
29	}) {
30	  const [menuOpen, setMenuOpen] = useState(false);
31	  const [showHourly, setShowHourly] = useState(false);
32	  // laterSentence === lead + adviceClause; render the clause in rust (README §2).
33	  const lead = weather.laterSentence.slice(0, weather.laterSentence.length - weather.adviceClause.length);
34	
35	  return (
36	    <div className="relative">
37	      <div className="flex items-baseline gap-2 text-sm">
38	        <span className="font-serif text-[21px] text-foreground">{formatTemp(weather.tempC, weather.tempUnit)}</span>
39	        <span className="max-w-[9rem] truncate text-[12.5px] text-muted-foreground">{weather.condition}</span>
40	        <span className="text-faint">·</span>
41	        <button
42	          type="button"
43	          aria-haspopup="listbox"
44	          aria-expanded={menuOpen}
45	          onClick={() => setMenuOpen((o) => !o)}
46	          className="inline-flex items-center gap-1 text-[12.5px] text-foreground"
47	        >
48	          <svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
49	            <path d="M12 2a7 7 0 0 0-7 7c0 5 7 13 7 13s7-8 7-13a7 7 0 0 0-7-7zm0 9.5A2.5 2.5 0 1 1 12 6a2.5 2.5 0 0 1 0 5.5z" />
50	          </svg>
51	          <span>{weather.cityLabel}</span>
52	          <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" aria-hidden="true">
53	            <path d="M6 9l6 6 6-6" strokeLinecap="round" strokeLinejoin="round" />
54	          </svg>
55	        </button>
56	        <span className="text-[11px] text-muted-dim">feels {formatTemp(weather.feelsLikeC, weather.tempUnit)}</span>
57	      </div>
58	
59	      {(locating || geoError) && (
60	        <p role="status" className="mt-1 text-[11.5px] text-muted-foreground">
61	          {locating ? "Locating…" : geoError}
62	        </p>
63	      )}
64	
65	      {menuOpen && (
66	        <LocationPicker
67	          className="absolute z-20 mt-2 w-full"
68	          cities={cities}
69	          currentLabel={weather.cityLabel}
70	          onSearch={(q) => onSearch?.(q)}
71	          onPick={(c) => {
72	            onCityChange?.(c);
73	            setMenuOpen(false);
74	          }}
75	          onUseMyLocation={
76	            onUseMyLocation
77	              ? () => {
78	                  onUseMyLocation();
79	                  setMenuOpen(false);
80	                }
81	              : undefined
82	          }
83	        />
84	      )}
85	
86	      <button
87	        type="button"
88	        data-testid="later-toggle"
89	        aria-expanded={showHourly}
90	        onClick={() => setShowHourly((s) => !s)}
91	        className="mt-[7px] flex w-full items-center gap-2 text-left text-[11.5px] text-muted-foreground"
92	      >
93	        <span className="text-[9px] uppercase tracking-[0.16em] text-muted-dim">{weather.laterLabel}</span>
94	        <span className="h-[3px] w-[3px] rounded-full bg-faint" />
95	        <span>
96	          {lead}
97	          <b className="font-semibold text-brand-high">{weather.adviceClause}</b>
98	        </span>
99	        <svg
100	          className={cn("ml-auto h-[11px] w-[11px] shrink-0 text-muted-dim transition-transform", showHourly && "rotate-180")}
101	          viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" aria-hidden="true"
102	        >
103	          <path d="M6 9l6 6 6-6" strokeLinecap="round" strokeLinejoin="round" />
104	        </svg>
105	      </button>
106	
107	      {showHourly && (
108	        <div data-testid="hourly" className="mt-[10px] flex gap-[7px]">
109	          {weather.hourly.map((h, i) => (
110	            <div
111	              key={i}
112	              data-now={h.isNow}
113	              className={cn(
114	                "flex-1 rounded-[11px] border p-2 text-center",
115	                h.isNow ? cn(HAIR2, "bg-foreground/5") : HAIR,
116	              )}
117	            >
118	              <div className={cn("text-[9px]", h.isNow ? "text-brand-high" : "text-muted-dim")}>
119	                {h.isNow ? "Now" : h.hh}
120	              </div>
121	              <div
122	                data-rain={h.rain}
123	                className={cn("mx-auto my-1 h-[18px] w-[18px]", h.rain ? "text-brand-high" : "text-muted-foreground")}
124	              >
125	                <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
126	                  <path d="M7 18a4.5 4.5 0 0 1-.5-8.97 5.5 5.5 0 0 1 10.6-.5A4 4 0 0 1 17 18z" />
127	                </svg>
128	              </div>
129	              <div className="text-[11.5px] text-foreground">{formatTemp(h.tempC, weather.tempUnit)}</div>
130	            </div>
131	          ))}
132	        </div>
133	      )}
134	    </div>
135	  );
136	}
